from collections import Counter, deque

def transform(grid):
    H = len(grid); W = len(grid[0])
    g = [row[:] for row in grid]
    cnt = Counter(c for row in grid for c in row)
    bg = cnt.most_common(1)[0][0]
    seen = [[False]*W for _ in range(H)]
    comps = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] != bg and not seen[i][j]:
                col = grid[i][j]; q = deque([(i, j)]); seen[i][j] = True; cells = []
                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < H and 0 <= nx < W and not seen[ny][nx] and grid[ny][nx] == col:
                            seen[ny][nx] = True; q.append((ny, nx))
                mr = min(c[0] for c in cells); mc = min(c[1] for c in cells)
                shape = frozenset((y-mr, x-mc) for y, x in cells)
                comps.append({'color': col, 'cells': cells, 'shape': shape, 'size': len(cells)})

    def bboxarea(cells):
        rs = [c[0] for c in cells]; cs = [c[1] for c in cells]
        return (max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)

    lcomp = max(comps, key=lambda c: (bboxarea(c['cells']), c['size']))
    lcol = lcomp['color']; lcells = lcomp['cells']
    lcy = sum(c[0] for c in lcells)/len(lcells)
    lcx = sum(c[1] for c in lcells)/len(lcells)

    byshape = {}
    for c in comps:
        byshape.setdefault(c['shape'], []).append(c)
    best = None
    for s, lst in byshape.items():
        for a in range(len(lst)):
            for b in range(a+1, len(lst)):
                p, qq = lst[a], lst[b]
                if p['color'] != qq['color']:
                    if best is None or p['size'] > best[0]['size']:
                        best = (p, qq)
    if best:
        p, qq = best
        def d(c):
            cy = sum(y for y, x in c['cells'])/len(c['cells'])
            cx = sum(x for y, x in c['cells'])/len(c['cells'])
            return ((cy-lcy)**2 + (cx-lcx)**2) ** 0.5
        tgt = p if d(p) > d(qq) else qq
        for y, x in tgt['cells']:
            g[y][x] = lcol
    return g
